package store.cadera.cdrjobs.command;
import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.jetbrains.annotations.*;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.data.Database;import store.cadera.cdrjobs.gui.JobsMenu;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;import store.cadera.cdrjobs.util.*;import java.util.*;
public final class JobsCommand implements CommandExecutor,TabCompleter{private final CdrJobsPlugin plugin;private final Database db;private final JobsMenu menu;private final LevelService levels;private final MinerAbilityService miner;private final FarmerService farmer;private final HunterService hunter;public JobsCommand(CdrJobsPlugin p,Database d,JobsMenu m,LevelService l,MinerAbilityService mi,FarmerService f,HunterService h){plugin=p;db=d;menu=m;levels=l;miner=mi;farmer=f;hunter=h;}@Override public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String label,@NotNull String[]a){if(!(s instanceof Player p)){s.sendMessage(Colors.color(plugin.prefix()+plugin.message("player-only")));return true;}if(!p.hasPermission("cdrjobs.use")){p.sendMessage(Colors.color(plugin.prefix()+plugin.message("no-permission")));return true;}if(a.length==0){menu.openMain(p);return true;}String sub=a[0].toLowerCase();if(sub.equals("miner")||sub.equals("skills")){menu.openMiner(p);return true;}if(sub.equals("farmer")){menu.openFarmer(p);return true;}if(sub.equals("hunter")){menu.openHunter(p);return true;}if(sub.equals("trials")){String j=a.length>1?a[1].toLowerCase():"miner";if(j.equals("farmer"))menu.openFarmerTrials(p);else if(j.equals("hunter"))menu.openHunterTrials(p);else menu.openTrials(p);return true;}if(sub.equals("ability")){String j=a.length>1?a[1].toLowerCase():"miner";if(j.equals("farmer"))farmer.activate(p);else if(j.equals("hunter"))hunter.activate(p);else miner.activateRunicSurge(p);return true;}if(sub.equals("stats")){Player t=p;if(a.length>=2&&p.hasPermission("cdrjobs.admin")){Player f=Bukkit.getPlayerExact(a[1]);if(f!=null)t=f;}p.sendMessage(ChatColor.DARK_AQUA+"✦ CdrJobs — "+t.getName());for(JobType j:JobType.values()){if(!j.released())continue;JobProgress pr=db.getProgress(t.getUniqueId(),j);p.sendMessage(ChatColor.AQUA+j.displayName()+ChatColor.GRAY+" • "+JobRanks.title(j,pr.level())+ChatColor.WHITE+" | Lv."+pr.level()+" | "+(pr.level()>=levels.maxLevel()?"MAX":pr.xp()+"/"+levels.xpRequiredForNextLevel(pr.level())));}p.sendMessage(ChatColor.LIGHT_PURPLE+"Fate Essence: "+db.getFateEssence(t.getUniqueId()));return true;}menu.openMain(p);return true;}@Override public @Nullable List<String> onTabComplete(@NotNull CommandSender s,@NotNull Command c,@NotNull String alias,@NotNull String[]a){if(a.length==1)return List.of("stats","miner","farmer","hunter","trials","ability");if(a.length==2&&(a[0].equalsIgnoreCase("trials")||a[0].equalsIgnoreCase("ability")))return List.of("miner","farmer","hunter");if(a.length==2&&a[0].equalsIgnoreCase("stats")&&s.hasPermission("cdrjobs.admin")){List<String>n=new ArrayList<>();Bukkit.getOnlinePlayers().forEach(x->n.add(x.getName()));return n;}return List.of();}}
